g.script:
(function(){
  var URLS=["workday.com/home", "workday.com/people-analytics", "workday.com/people-analytics/org-health", "workday.com/people-analytics/quality-of-hire", "workday.com/people-analytics/quality-of-hire/services", "workday.com/people-analytics/quality-of-hire/services/ne"];
  var N=6, cur=0, svg=document.getElementById("pa-proto"), url=document.getElementById("url"), hint=document.getElementById("hint");
  function flash(){ var f=document.querySelectorAll("#s"+cur+" .flash");
    for(var k=0;k<f.length;k++){ (function(r){ r.setAttribute("fill-opacity","0.18"); r.setAttribute("stroke-opacity","1");
      setTimeout(function(){ r.setAttribute("fill-opacity","0"); r.setAttribute("stroke-opacity","0"); },700); })(f[k]); } }
  function go(i){ i=(i+N)%N; if(i===cur) return; var a=document.getElementById("s"+cur), b=document.getElementById("s"+i), was=cur;
    b.removeAttribute("visibility"); b.setAttribute("opacity","1"); a.setAttribute("opacity","0");
    setTimeout(function(){ if(was!==cur) a.setAttribute("visibility","hidden"); },320);
    cur=i; if(url) url.textContent=URLS[i]; hint.setAttribute("opacity","0"); }
  var hs=document.querySelectorAll(".hot");
  for(var j=0;j<hs.length;j++){ hs[j].addEventListener("click",function(e){ e.stopPropagation(); go(+this.getAttribute("data-go")); }); }
  // a click anywhere else: on the last screen it starts over, otherwise it shows where to click
  document.getElementById("viewport").addEventListener("click",function(){ if(cur===N-1) go(0); else flash(); });
  svg.addEventListener("keydown",function(e){ var m={ArrowRight:1,ArrowDown:1,PageDown:1,ArrowLeft:-1,ArrowUp:-1,PageUp:-1}[e.key];
    if(m){ e.preventDefault(); go(cur+m); } else if(e.key==="Home"){ e.preventDefault(); go(0); } });
  var shown=false;
  function intro(){ if(shown) return; shown=true; hint.setAttribute("opacity","1"); setTimeout(flash,600);
    setTimeout(function(){ hint.setAttribute("opacity","0"); },3200); }
  try{ new IntersectionObserver(function(es){ if(es[0].isIntersecting&&es[0].intersectionRatio>.5) intro(); },{threshold:[.5]}).observe(svg); }
  catch(_){ setTimeout(intro,600); }
  if(url) url.textContent=URLS[0];
})();
